import pytest
from unittest.mock import Mock, patch, MagicMock
import sys
import types

# Import the decorators module
from click.decorators import (
    pass_context,
    pass_obj,
    make_pass_decorator,
    pass_meta_key,
    command,
    group,
    _param_memo,
    argument,
    option,
