from click.core import Command, Group, Context, Argument, Option, Parameter


class TestPassContext:
    def test_pass_context_basic(self):
        """Test that pass_context passes the current context to the function."""
        @pass_context
        def callback(ctx, *args, **kwargs):
            return ctx, args, kwargs

        # Create a mock context
        mock_ctx = Mock(spec=Context)
        mock_ctx.name = "test"

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback("arg1", kwarg="value")
            assert result[0] is mock_ctx
            assert result[1] == ("arg1",)
            assert result[2] == {"kwarg": "value"}

    def test_pass_context_no_args(self):
        """Test pass_context with no additional arguments."""
        @pass_context
        def callback(ctx):
            return ctx.name

        mock_ctx = Mock(spec=Context)
        mock_ctx.name = "test_name"

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback()
            assert result == "test_name"


class TestPassObj:
    def test_pass_obj_basic(self):
        """Test that pass_obj passes ctx.obj to the function."""
        @pass_obj
        def callback(obj, *args, **kwargs):
            return obj, args, kwargs

        mock_ctx = Mock(spec=Context)
        mock_ctx.obj = {"key": "value"}

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback("arg1")
            assert result[0] == {"key": "value"}
            assert result[1] == ("arg1",)

    def test_pass_obj_with_none_obj(self):
        """Test pass_obj when ctx.obj is None."""
        @pass_obj
        def callback(obj):
            return obj

        mock_ctx = Mock(spec=Context)
        mock_ctx.obj = None

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback()
            assert result is None


class TestMakePassDecorator:
    def test_make_pass_decorator_basic(self):
        """Test make_pass_decorator creates a working decorator."""
        class CustomObject:
            def __init__(self, value):
                self.value = value

        decorator = make_pass_decorator(CustomObject)

        @decorator
        def callback(obj, x):
            return obj.value + x

        mock_ctx = Mock(spec=Context)
        mock_obj = CustomObject(10)
        mock_ctx.find_object.return_value = mock_obj

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback(5)
            assert result == 15

    def test_make_pass_decorator_ensure_true(self):
        """Test make_pass_decorator with ensure=True creates new object."""
        class CustomObject:
            def __init__(self, value):
                self.value = value

        decorator = make_pass_decorator(CustomObject, ensure=True)

        @decorator
        def callback(obj, x):
            return obj.value + x

        mock_ctx = Mock(spec=Context)
        mock_obj = CustomObject(10)
        mock_ctx.ensure_object.return_value = mock_obj

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback(5)
            assert result == 15
            mock_ctx.ensure_object.assert_called_once()

    def test_make_pass_decorator_missing_object(self):
        """Test make_pass_decorator raises error when object not found."""
        decorator = make_pass_decorator(dict)

        @decorator
        def callback(obj):
            return obj

        mock_ctx = Mock(spec=Context)
        mock_ctx.find_object.return_value = None

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            with pytest.raises(RuntimeError, match="Managed to invoke callback"):
                callback()


class TestPassMetaKey:
    def test_pass_meta_key_basic(self):
        """Test pass_meta_key passes meta key value to function."""
