            return value

        mock_ctx = Mock(spec=Context)
        mock_ctx.meta = {"my_key": "test_value"}

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = callback()
            assert result == "test_value"

    def test_pass_meta_key_custom_doc_description(self):
