        assert "custom description" in callback.__doc__


class TestCommand:
    def test_command_basic_decorator(self):
        """Test basic command decorator usage."""
        @command()
        def cli():
            return "hello"

        assert isinstance(cli, Command)
        assert cli.callback is cli

    def test_command_with_name(self):
        """Test command with explicit name."""
        @command(name="my-command")
        def cli():
            return "hello"

        assert cli.name == "my-command"

    def test_command_without_parentheses(self):
        """Test command decorator without parentheses."""
        @command
        def cli():
            return "hello"

        assert isinstance(cli, Command)

    def test_command_with_cls(self):
        """Test command with custom class."""
        class CustomCommand(Command):
            pass

        @command(cls=CustomCommand)
        def cli():
            return "hello"

        assert isinstance(cli, CustomCommand)

    def test_command_params_from_decorators(self):
        """Test that params from decorators are attached."""
        @command()
        @option("--name")
        def cli(name):
            return name

        assert len(cli.params) > 0
        param_names = [p.name for p in cli.params]
        assert "name" in param_names

    def test_command_help_from_docstring(self):
        """Test that help is taken from docstring."""
        @command()
        def cli():
            """This is my help text."""
            pass

        assert cli.help == "This is my help text."

    def test_command_double_conversion_error(self):
        """Test error when converting already converted callback."""
        cmd = Command("test", lambda: None)

        with pytest.raises(TypeError, match="Attempted to convert"):
            @command
            def cli(cmd):
                pass


