class TestParamMemo:
    def test_param_memo_on_command(self):
        """Test _param_memo on Command instance."""
        cmd = Command("test", lambda: None)
        param = Argument(["arg"])

        _param_memo(cmd, param)
        assert param in cmd.params

    def test_param_memo_on_function(self):
        """Test _param_memo on function."""
        def func():
            pass

        param = Argument(["arg"])
        _param_memo(func, param)

        assert hasattr(func, "__click_params__")
        assert param in func.__click_params__


