class TestIntegration:
    def test_command_with_all_decorators(self):
        """Test command with multiple decorators combined."""
        @command()
        @argument("name")
        @option("--verbose", is_flag=True)
        def cli(name, verbose):
            if verbose:
                return f"Verbose: {name}"
            return name

        assert isinstance(cli, Command)
        assert len(cli.params) >= 2

    def test_group_with_commands(self):
        """Test group containing commands."""
        @group()
        def cli():
            pass

        @cli.command()
        def subcommand():
            return "sub"

        assert hasattr(cli, 'commands')
        assert 'subcommand' in cli.commands

    def test_nested_pass_context(self):
        """Test nested pass_context decorators."""
        @pass_context
        def outer(ctx, inner_func):
            return inner_func(ctx)

        @pass_context
        def inner(ctx):
            return ctx.name

        mock_ctx = Mock(spec=Context)
        mock_ctx.name = "nested_test"

        with patch('click.decorators.get_current_context', return_value=mock_ctx):
            result = outer(inner)
            assert result == "nested_test"

