class TestHiddenPromptFunc:
    def test_hidden_prompt_func_calls_getpass(self):
        with mock.patch('click.termui.getpass.getpass') as mock_getpass:
            mock_getpass.return_value = "secret_password"
            result = hidden_prompt_func("Enter password: ")
            assert result == "secret_password"
