class TestBuildPrompt:
    def test_build_prompt_basic(self):
        result = _build_prompt("Enter value", ": ")
        assert result == "Enter value: "

    def test_build_prompt_with_choices(self):
        choice_type = Choice(["option1", "option2"])
        result = _build_prompt("Select", ": ", show_choices=True, type=choice_type)
        assert "(option1, option2)" in result

    def test_build_prompt_with_default(self):
        result = _build_prompt("Enter", ": ", show_default=True, default="test")
        assert "[test]" in result

    def test_build_prompt_without_choices(self):
        result = _build_prompt("Select", ": ", show_choices=False, type=Choice(["a", "b"]))
        assert "(" not in result

    def test_build_prompt_without_default(self):
        result = _build_prompt("Enter", ": ", show_default=False, default="test")
        assert "[" not in result


