class TestStyle:
    def test_style_fg_color(self):
        result = style("Hello", fg="red")
        assert "\033[31m" in result
        assert "Hello" in result
        assert "\033[0m" in result

    def test_style_bg_color(self):
        result = style("Hello", bg="blue")
        assert "\033[44m" in result

    def test_style_bold(self):
        result = style("Hello", bold=True)
        assert "\033[1m" in result

    def test_style_dim(self):
        result = style("Hello", dim=True)
        assert "\033[2m" in result

    def test_style_underline(self):
        result = style("Hello", underline=True)
        assert "\033[4m" in result

    def test_style_overline(self):
        result = style("Hello", overline=True)
        assert "\033[53m" in result

    def test_style_italic(self):
        result = style("Hello", italic=True)
        assert "\033[3m" in result

    def test_style_blink(self):
        result = style("Hello", blink=True)
        assert "\033[5m" in result

    def test_style_reverse(self):
        result = style("Hello", reverse=True)
        assert "\033[7m" in result

    def test_style_strikethrough(self):
        result = style("Hello", strikethrough=True)
        assert "\033[9m" in result

    def test_style_reset_false(self):
        result = style("Hello", fg="red", reset=False)
        assert "\033[0m" not in result

    def test_style_unknown_color(self):
        with pytest.raises(TypeError):
            style("Hello", fg="unknown_color")

    def test_style_rgb_color(self):
        result = style("Hello", fg=(255, 128, 0))
        assert "\033[38;2;255;128;0m" in result

    def test_style_256_color(self):
        result = style("Hello", fg=100)
        assert "\033[38;5;100m" in result

    def test_style_non_string_text(self):
        result = style(123, fg="red")
        assert "123" in result

    def test_style_multiple_styles(self):
        result = style("Hello", fg="green", bold=True, underline=True)
        assert "\033[32m" in result
        assert "\033[1m" in result
        assert "\033[4m" in result


