class TestLazyFile:
    def test_init_with_dash(self):
        lf = LazyFile("-", "r")
        assert lf.name == "-"
        assert lf.mode == "r"

    def test_init_with_regular_file(self):
        with tempfile.NamedTemporaryFile(delete=False) as f:
            temp_path = f.name
        try:
            lf = LazyFile(temp_path, "r")
            assert lf.name == temp_path
        finally:
            os.unlink(temp_path)

    def test_repr_unopened(self):
        lf = LazyFile("/tmp/test.txt", "r")
        repr_str = repr(lf)
        assert "unopened" in repr_str.lower()

    def test_open_method(self):
        with tempfile.NamedTemporaryFile(mode="w", delete=False) as f:
            temp_path = f.name
            f.write("test content")
        try:
            lf = LazyFile(temp_path, "r")
            file_obj = lf.open()
            assert file_obj.read() == "test content"
            file_obj.close()
        finally:
            os.unlink(temp_path)

    def test_context_manager(self):
        with tempfile.NamedTemporaryFile(mode="w", delete=False) as f:
            temp_path = f.name
            f.write("test")
        try:
            with LazyFile(temp_path, "r") as lf:
                assert lf._f is not None
            # File should be closed after context manager exits
        finally:
            os.unlink(temp_path)

    def test_close_intelligently(self):
        lf = LazyFile("-", "r")
        lf.should_close = True
        lf.close_intelligently()

    def test_iter_method(self):
        with tempfile.NamedTemporaryFile(mode="w", delete=False) as f:
            temp_path = f.name
            f.write("line1\nline2\n")
        try:
            lf = LazyFile(temp_path, "r")
            lines = list(lf)
            assert len(lines) == 2
        finally:
            os.unlink(temp_path)


