class TestPacifyFlushWrapper:
    def test_flush_success(self):
        wrapped = io.StringIO()
        pfw = PacifyFlushWrapper(wrapped)
        pfw.flush()  # Should not raise

    def test_flush_broken_pipe(self):
        import errno

        wrapped = io.StringIO()
        original_flush = wrapped.flush

        def failing_flush():
            raise OSError(errno.EPIPE, "Broken pipe")

        wrapped.flush = failing_flush
        pfw = PacifyFlushWrapper(wrapped)
        pfw.flush()  # Should suppress EPIPE

    def test_flush_other_oserror(self):
        import errno

        wrapped = io.StringIO()
        original_flush = wrapped.flush

        def failing_flush():
            raise OSError(errno.ENOENT, "No such file")

        wrapped.flush = failing_flush
        pfw = PacifyFlushWrapper(wrapped)
        with pytest.raises(OSError):
            pfw.flush()

    def test_getattr_proxy(self):
        wrapped = io.StringIO("test")
        pfw = PacifyFlushWrapper(wrapped)
        assert pfw.read() == "test"


