        assert result == 11

    def test_super_len_with_bytes(self):
        b = b"hello world"
        result = super_len(b)
        assert result == 11

    def test_super_len_with_file_like_object(self):
        f = io.BytesIO(b"hello world")
        result = super_len(f)
        assert result == 11

    def test_super_len_with_partial_read(self):
        f = io.BytesIO(b"hello world")
        f.read(5)
        result = super_len(f)
        assert result == 6

    def test_super_len_with_fileno(self):
        with tempfile.NamedTemporaryFile(delete=False) as tmp:
            tmp.write(b"test data")
            tmp_path = tmp.name
        try:
            with open(tmp_path, 'rb') as f:
                result = super_len(f)
                assert result == 9
        finally:
            os.unlink(tmp_path)

    def test_super_len_with_text_mode_warning(self):
        with tempfile.NamedTemporaryFile(mode='w', delete=False) as tmp:
            tmp.write("test data")
            tmp_path = tmp.name
        try:
            with open(tmp_path, 'r') as f:
                with warnings.catch_warnings(record=True) as w:
                    warnings.simplefilter("always")
                    super_len(f)
                    assert len(w) > 0
                    assert "FileModeWarning" in str(w[0].category)
        finally:
            os.unlink(tmp_path)

    def test_super_len_with_zero_length(self):
        f = io.BytesIO()
        result = super_len(f)
        assert result == 0


