class TestStreamWithContext:
    @patch('flask.helpers._cv_request')
    def test_stream_with_context_generator(self, mock_cv_request):
        """Test stream_with_context with a generator"""
        mock_ctx = MagicMock()
        mock_ctx.__enter__ = Mock(return_value=None)
        mock_ctx.__exit__ = Mock(return_value=None)
        mock_cv_request.get.return_value = mock_ctx

        def gen():
            yield "hello"
            yield "world"

        result = stream_with_context(gen)
        items = list(result)
        assert items == ["hello", "world"]

    @patch('flask.helpers._cv_request')
    def test_stream_with_context_decorator(self, mock_cv_request):
        """Test stream_with_context as decorator"""
        mock_ctx = MagicMock()
        mock_ctx.__enter__ = Mock(return_value=None)
        mock_ctx.__exit__ = Mock(return_value=None)
        mock_cv_request.get.return_value = mock_ctx

        def func():
            yield "a"
            yield "b"

        decorated = stream_with_context(func)
        result = decorated()
        items = list(result)
        assert items == ["a", "b"]

    @patch('flask.helpers._cv_request')
    def test_stream_with_context_no_context(self, mock_cv_request):
        """Test stream_with_context raises error when no context"""
        mock_cv_request.get.return_value = None

        def gen():
            yield "test"

        result = stream_with_context(gen)
        with pytest.raises(RuntimeError, match="'stream_with_context' can only be used"):
            next(result)

    @patch('flask.helpers._cv_request')
    def test_stream_with_context_not_iterable(self, mock_cv_request):
        """Test stream_with_context with non-iterable input"""
        mock_ctx = MagicMock()
        mock_ctx.__enter__ = Mock(return_value=None)
        mock_ctx.__exit__ = Mock(return_value=None)
        mock_cv_request.get.return_value = mock_ctx

        def func(a, b):
            yield a
            yield b

        decorated = stream_with_context(func)
        result = decorated(1, 2)
        items = list(result)
        assert items == [1, 2]


