        result = safe_range(0, 10, 2)
        assert list(result) == [0, 2, 4, 6, 8]

    def test_safe_range_too_big_raises_overflow(self):
        with pytest.raises(OverflowError) as exc_info:
            safe_range(MAX_RANGE + 1)
        assert "Range too big" in str(exc_info.value)

