class TestParseResult:
    def test_parse_result_basic(self):
        result = urlparse("https://example.com/path?query=1#fragment")
        assert result.scheme == "https"
        assert result.userinfo == ""
        assert result.host == "example.com"
        assert result.port is None
        assert result.path == "/path"
        assert result.query == "query=1"
        assert result.fragment == "fragment"

    def test_parse_result_authority_property(self):
        result = urlparse("https://user@example.com:8080/path")
        assert result.authority == "user@example.com:8080"

    def test_parse_result_authority_no_userinfo(self):
        result = urlparse("https://example.com:8080/path")
        assert result.authority == "example.com:8080"

    def test_parse_result_netloc_ipv6(self):
        result = urlparse("https://[::1]:8080/path")
        assert result.netloc == "[::1]:8080"

    def test_parse_result_str_representation(self):
        result = urlparse("https://example.com/path?query=1#fragment")
        assert str(result) == "https://example.com/path?query=1#fragment"

    def test_parse_result_str_no_query_or_fragment(self):
        result = urlparse("https://example.com/path")
        assert str(result) == "https://example.com/path"

    def test_parse_result_copy_with(self):
        result = urlparse("https://example.com/path?query=1#fragment")
        new_result = result.copy_with(path="/newpath")
        assert new_result.path == "/newpath"
        assert new_result.scheme == "https"

    def test_parse_result_copy_with_empty_kwargs(self):
        result = urlparse("https://example.com/path")
        new_result = result.copy_with()
        assert new_result == result

    def test_parse_result_copy_with_scheme(self):
        result = urlparse("https://example.com/path")
        new_result = result.copy_with(scheme="http")
        assert new_result.scheme == "http"

    def test_parse_result_copy_with_none_values(self):
        result = urlparse("https://example.com/path?query=1#fragment")
        new_result = result.copy_with(query=None, fragment=None)
        assert new_result.query is None
        assert new_result.fragment is None


class TestUrlParseBasic:
