class TestUrlParseValidation:
    def test_url_too_long(self):
        with pytest.raises(InvalidURL, match="URL too long"):
            urlparse("a" * (MAX_URL_LENGTH + 1))

    def test_url_with_control_characters(self):
        with pytest.raises(InvalidURL, match="Invalid non-printable ASCII character"):
            urlparse("http://example.com/\n")

    def test_invalid_component_too_long(self):
        with pytest.raises(InvalidURL, match="component.*too long"):
            urlparse("", path="a" * (MAX_URL_LENGTH + 1))

    def test_invalid_component_control_characters(self):
        with pytest.raises(InvalidURL, match="component.*non-printable"):
            urlparse("", path="path\nwith\nnewline")

    def test_invalid_scheme(self):
        with pytest.raises(InvalidURL):
            urlparse("123invalid://example.com")

    def test_invalid_ipv4_address(self):
        with pytest.raises(InvalidURL, match="Invalid IPv4 address"):
            urlparse("http://999.999.999.999/path")

    def test_invalid_ipv6_address(self):
        with pytest.raises(InvalidURL, match="Invalid IPv6 address"):
            urlparse("http://[::g]/path")

    def test_invalid_idna_hostname(self):
        with pytest.raises(InvalidURL, match="Invalid IDNA hostname"):
            urlparse("http://\udcff.example.com/path")

    def test_invalid_port_non_integer(self):
        with pytest.raises(InvalidURL, match="Invalid port"):
            urlparse("http://example.com:abc/path")

    def test_invalid_port_negative(self):
        with pytest.raises(InvalidURL):
            urlparse("http://example.com:-1/path")

    def test_invalid_port_zero(self):
        with pytest.raises(InvalidURL):
            urlparse("http://example.com:0/path")


