class TestWrapSerializer:
    """Tests for WrapSerializer class."""

    def test_wrap_serializer_basic(self):
        """Test basic wrap serializer functionality."""
        def wrap_serialize(value: int, handler, info) -> str:
            result = handler(value)
            return f"wrapped_{result}"

        WrappedInt = Annotated[
            int, WrapSerializer(wrap_serialize, return_type=str)
        ]

        class Model(BaseModel):
            value: WrappedInt

        m = Model(value=5)
        assert m.model_dump() == {'value': 'wrapped_5'}

    def test_wrap_serializer_modify_result(self):
        """Test wrap serializer that modifies the handler result."""
        def double_value(value: int, handler, info) -> int:
            result = handler(value)
            return result * 2

        DoubledInt = Annotated[
            int, WrapSerializer(double_value, return_type=int)
        ]

        class Model(BaseModel):
            value: DoubledInt

        m = Model(value=5)
        assert m.model_dump() == {'value': 10}

    def test_wrap_serializer_datetime_utc_conversion(self):
        """Test wrap serializer for datetime UTC conversion."""
        def convert_to_utc(value: Any, handler, info) -> Dict[str, datetime]:
            partial_result = handler(value, info)
            if isinstance(partial_result, dict):
                return {
                    k: datetime.fromisoformat(v).astimezone(timezone.utc)
                    for k, v in partial_result.items()
                }
            return partial_result

        class EventDatetime(BaseModel):
            start: datetime
            end: datetime

        UTCEventDatetime = Annotated[EventDatetime, WrapSerializer(convert_to_utc)]

        class EventModel(BaseModel):
            event_datetime: UTCEventDatetime

        dt = EventDatetime(
            start='2024-01-01T07:00:00-08:00', 
            end='2024-01-03T20:00:00+06:00'
        )
        event = EventModel(event_datetime=dt)
        result = event.model_dump()

        assert 'start' in result['event_datetime']
        assert 'end' in result['event_datetime']
        assert result['event_datetime']['start'].tzinfo == timezone.utc
        assert result['event_datetime']['end'].tzinfo == timezone.utc

    def test_wrap_serializer_when_used_always(self):
        """Test wrap serializer with when_used='always'."""
        def wrap_func(value: int, handler, info) -> str:
            return handler(value) + "_always"

        WrappedInt = Annotated[
            int, WrapSerializer(wrap_func, return_type=str, when_used='always')
        ]

        class Model(BaseModel):
            value: WrappedInt

        m = Model(value=5)
        assert m.model_dump() == {'value': '5_always'}

    def test_wrap_serializer_when_used_unless_none(self):
        """Test wrap serializer with when_used='unless-none'."""
        def wrap_func(value: int, handler, info) -> str:
            return handler(value) + "_unless_none"

        WrappedInt = Annotated[
