            int | None, PlainSerializer(lambda x: str(x) if x else 'none', return_type=str)
        ]

        class Model(BaseModel):
            value: CustomInt

        m = Model(value=None)
        assert m.model_dump() == {'value': 'none'}

    def test_wrap_serializer_preserves_handler_behavior(self):
        """Test that wrap serializer can call handler properly."""
        def wrap_with_handler(value: int, handler, info) -> int:
            if value < 0:
                return 0
            return handler(value)

        WrappedInt = Annotated[
            int, WrapSerializer(wrap_with_handler, return_type=int)
        ]

        class Model(BaseModel):
            value: WrappedInt

        m1 = Model(value=-5)
        assert m1.model_dump() == {'value': 0}

        m2 = Model(value=5)
        assert m2.model_dump() == {'value': 5}

    def test_field_serializer_with_self_parameter(self):
        """Test field_serializer with self parameter."""
        class Model(BaseModel):
            value: int

            @field_serializer('value')
            def serialize_value(self, value: int) -> str:
                return f"{self.__class__.__name__}_{value}"

        m = Model(value=5)
        assert m.model_dump() == {'value': 'Model_5'}

    def test_model_serializer_with_classmethod(self):
        """Test model_serializer with classmethod."""
        class Model(BaseModel):
            value: int

            @classmethod
            @model_serializer
            def serialize_model(cls, self):
                return {'cls_name': cls.__name__, 'value': self.value}

        m = Model(value=5)
        result = m.model_dump()
        assert result['cls_name'] == 'Model'
        assert result['value'] == 5

    def test_complex_serialization_chain(self):
        """Test complex serialization with multiple decorators."""
        from typing_extensions import Annotated

        def add_prefix(value: int, handler, info) -> str:
            return f"prefix_{handler(value)}"

        def multiply(value: int) -> int:
            return value * 2

        MultipliedInt = Annotated[
            int, 
            PlainSerializer(multiply, return_type=int),
            WrapSerializer(add_prefix, return_type=str)
        ]

        class Model(BaseModel):
            value: MultipliedInt

        m = Model(value=5)
        result = m.model_dump()
        assert result['value'] == 'prefix_10'


class TestDecoratorInfo:
    """Tests for decorator information storage."""

    def test_field_serializer_decorator_info(self):
        """Test that field_serializer stores decorator info correctly."""
        class Model(BaseModel):
            value: int

            @field_serializer('value', mode='wrap', when_used='json')
            def serialize_value(self, value: int, handler, info) -> str:
                return handler(value)

        # Verify the decorator was applied
        m = Model(value=5)
        json_result = m.model_dump_json()
        assert '5' in json_result

    def test_model_serializer_decorator_info(self):
        """Test that model_serializer stores decorator info correctly."""
        class Model(BaseModel):
            value: int

            @model_serializer(mode='wrap', when_used='json')
            def serialize_model(self, handler):
                result = handler(self)
                result['processed'] = True
                return result

        m = Model(value=5)
        json_result = m.model_dump_json()
        assert 'processed' in json_result

