    def test_wrap_validator_basic(self):
        """Test basic WrapValidator functionality."""
        def validate_timestamp(v, handler):
            if v == 'now':
                return datetime.now()
            try:
                return handler(v)
            except Exception:
                return datetime(2000, 1, 1)

        MyTimestamp = Annotated[datetime, WrapValidator(validate_timestamp)]

        class Model(BaseModel):
            a: MyTimestamp

        result = Model(a='now').a
        assert isinstance(result, datetime)

        result = Model(a='invalid').a
        assert result == datetime(2000, 1, 1)

    def test_wrap_validator_with_info(self):
        """Test WrapValidator with info argument."""
        def validate_with_info(v, handler, info):
            if v < 0:
                raise ValueError("Value must be positive")
            return handler(v)

        MyInt = Annotated[int, WrapValidator(validate_with_info)]

        class Model(BaseModel):
            a: MyInt

        assert Model(a=5).a == 5

        with pytest.raises(ValidationError):
            Model(a=-1)

    def test_wrap_validator_no_handler_call(self):
        """Test WrapValidator that doesn't call handler."""
        def skip_handler(v, handler):
            return 'custom'

        MyStr = Annotated[str, WrapValidator(skip_handler)]

        class Model(BaseModel):
            a: MyStr

        assert Model(a=123).a == 'custom'


