class TestModelValidator:
    """Tests for model_validator decorator."""

    def test_model_validator_after_mode(self):
        """Test model_validator with after mode."""
        from typing_extensions import Self

        class Square(BaseModel):
            width: float
            height: float

            @model_validator(mode='after')
            def verify_square(self) -> Self:
                if self.width != self.height:
                    raise ValueError('width and height do not match')
                return self

        s = Square(width=1, height=1)
        assert repr(s) == 'Square(width=1.0, height=1.0)'

        with pytest.raises(ValidationError):
            Square(width=1, height=2)

    def test_model_validator_before_mode(self):
        """Test model_validator with before mode."""
        class Model(BaseModel):
            a: int
            b: int

            @model_validator(mode='before')
            @classmethod
            def add_fields(cls, values):
                if 'a' in values and 'b' not in values:
                    values['b'] = values['a']
                return values

        m = Model(a=5)
        assert m.a == 5
        assert m.b == 5

    def test_model_validator_wrap_mode(self):
        """Test model_validator with wrap mode."""
        from typing_extensions import Self

        class Model(BaseModel):
            value: int

            @model_validator(mode='wrap')
            @classmethod
            def validate_value(cls, v, handler, info):
                if v < 0:
                    raise ValueError("Value must be positive")
                return handler(v)

        m = Model(value=5)
        assert m.value == 5

        with pytest.raises(ValidationError):
            Model(value=-1)

    def test_model_validator_without_info(self):
        """Test model_validator without info argument."""
        from typing_extensions import Self

        class Model(BaseModel):
            value: int

            @model_validator(mode='after')
            def validate_value(self) -> Self:
                if self.value < 0:
                    raise ValueError("Value must be positive")
                return self

        m = Model(value=5)
        assert m.value == 5

        with pytest.raises(ValidationError):
            Model(value=-1)


