class TestValidatorEdgeCases:
    """Tests for edge cases in validators."""

    def test_validator_none_value(self):
        """Test validator with None value."""
        MyInt = Annotated[int | None, AfterValidator(lambda v: v if v is None else v + 1)]

        class Model(BaseModel):
            a: MyInt

        assert Model(a=None).a is None
        assert Model(a=1).a == 2

    def test_validator_empty_string(self):
        """Test validator with empty string."""
        MyStr = Annotated[str, AfterValidator(lambda v: v or 'default')]

        class Model(BaseModel):
            a: MyStr

        assert Model(a='').a == 'default'

    def test_validator_special_characters(self):
        """Test validator with special characters."""
        MyStr = Annotated[str, BeforeValidator(lambda v: v.strip())]

        class Model(BaseModel):
            a: MyStr

        assert Model(a='  hello  ').a == 'hello'

    def test_validator_large_number(self):
        """Test validator with large number."""
        MyInt = Annotated[int, AfterValidator(lambda v: v * 2)]

        class Model(BaseModel):
            a: MyInt

        assert Model(a=10**9).a == 2 * 10**9

