class TestCachedProperty:
    def test_basic_functionality(self):
        class Example:
            @cached_property
            def value(self):
                return 42

        e = Example()
        assert e.value == 42
        # Second access should use cache
        assert e.value == 42

    def test_cache_clear_on_delete(self):
        class Example:
            _cache_value = None

            @cached_property
            def value(self):
                return 42

        e = Example()
        assert e.value == 42
        del e.value
        assert e.value == 42  # Will re-evaluate

    def test_set_cache(self):
        class Example:
            @cached_property
            def value(self):
                return 42

        e = Example()
        assert e.value == 42
        e.value = 16
        assert e.value == 16

    def test_with_slots(self):
        class Example:
            __slots__ = ("_cache_value",)

            @cached_property
            def value(self):
                return 42

        e = Example()
        assert e.value == 42
        assert hasattr(e, "_cache_value")


