class TestSecureFilename:
    def test_basic_filename(self):
        result = secure_filename("My cool movie.mov")
        assert result == "My_cool_movie.mov"

    def test_path_traversal(self):
        result = secure_filename("../../../etc/passwd")
        assert result == "etc_passwd"

    def test_unicode_filename(self):
        result = secure_filename('i contain cool ümläuts.txt')
        assert result == "i_contain_cool_umlauts.txt"

    def test_empty_result(self):
        result = secure_filename("...")
        assert result == ""

    def test_special_windows_devices(self):
        result = secure_filename("CON")
        assert result.startswith("_")

    def test_multiple_separators(self):
        result = secure_filename("path/to/file.txt")
        assert "/" not in result and "\\" not in result

    def test_leading_dots_stripped(self):
        result = secure_filename(".hidden")
        assert result == "hidden"


class TestRedirect:
    def test_basic_redirect(self):
        response = redirect("/target")
        assert response.status_code == 302
        assert response.headers["Location"] == "/target"

    def test_custom_code(self):
        response = redirect("/target", code=301)
        assert response.status_code == 301

    def test_html_content(self):
        response = redirect("/target")
        assert b"Redirecting..." in response.get_data(as_text=True).encode()
        assert b"/target" in response.get_data(as_text=True).encode()

    def test_response_class(self):
        class CustomResponse:
            pass

        with patch("werkzeug.utils.Response", CustomResponse):
            response = redirect("/target")
            assert isinstance(response, CustomResponse)


