        with tempfile.NamedTemporaryFile(delete=False) as f:
            f.write(b"test content")
            temp_path = f.name

        try:
            environ = {"PATH_INFO": "/test", "QUERY_STRING": ""}
            response = send_file(temp_path, environ)
            assert response.status_code == 200
            assert b"test content" in response.get_data()
        finally:
            os.unlink(temp_path)

