        with tempfile.TemporaryDirectory() as tmpdir:
            environ = {"PATH_INFO": "/test", "QUERY_STRING": ""}
            with pytest.raises(NotFound):
                send_from_directory(tmpdir, "nonexistent.txt", environ)

    def test_send_from_directory_path_traversal(self):
