class TestImportString:
    def test_import_module(self):
        result = import_string("os")
        assert result is not None

    def test_import_function(self):
        result = import_string("os.path.join")
        assert callable(result)

    def test_import_with_colon(self):
        result = import_string("os:path.join")
        assert callable(result)

    def test_silent_failure(self):
        result = import_string("nonexistent.module", silent=True)
        assert result is None

    def test_non_silent_failure(self):
        with pytest.raises(ImportStringError):
            import_string("nonexistent.module", silent=False)

    def test_attribute_error(self):
        with pytest.raises(ImportStringError):
            import_string("os.nonexistent_attribute", silent=False)


