class TestImportStringError:
    def test_init(self):
        error = ImportStringError("test.module", ImportError("test"))
        assert error.import_name == "test.module"
        assert isinstance(error.exception, ImportError)

    def test_repr(self):
        error = ImportStringError("test.module", ImportError("test"))
        repr_str = repr(error)
        assert "ImportStringError" in repr_str
        assert "test.module" in repr_str

