class TestResponder:
    def test_responder_decorator(self):
        @responder
        def app(environ, start_response):
            return [b"Hello World"]

        environ = {"wsgi.url_scheme": "http"}
        start_response = MagicMock()
        result = app(environ, start_response)
        assert list(result) == [b"Hello World"]

    def test_responder_preserves_metadata(self):
        @responder
        def app(environ, start_response):
            """App docstring"""
            return [b"Test"]

        assert app.__name__ == "app"
        assert app.__doc__ == "App docstring"


class TestGetCurrentUrl:
    def test_get_current_url_basic(self):
        environ = {
            "wsgi.url_scheme": "https",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "443",
            "SCRIPT_NAME": "",
            "PATH_INFO": "/test",
            "QUERY_STRING": "foo=bar",
        }
        url = get_current_url(environ)
        assert "https://example.com/test" in url
        assert "foo=bar" in url

    def test_get_current_url_root_only(self):
        environ = {
            "wsgi.url_scheme": "http",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "80",
            "SCRIPT_NAME": "/app",
            "PATH_INFO": "/test",
            "QUERY_STRING": "foo=bar",
        }
        url = get_current_url(environ, root_only=True)
        assert "/app" in url
        assert "/test" not in url
        assert "foo=bar" not in url

    def test_get_current_url_strip_querystring(self):
        environ = {
            "wsgi.url_scheme": "http",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "80",
            "SCRIPT_NAME": "",
            "PATH_INFO": "/test",
            "QUERY_STRING": "foo=bar",
        }
        url = get_current_url(environ, strip_querystring=True)
        assert "foo=bar" not in url

    def test_get_current_url_host_only(self):
        environ = {
            "wsgi.url_scheme": "https",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "443",
            "SCRIPT_NAME": "/app",
            "PATH_INFO": "/test",
            "QUERY_STRING": "foo=bar",
        }
        url = get_current_url(environ, host_only=True)
        assert "https://example.com" in url
        assert "/app" not in url
        assert "/test" not in url

    def test_get_current_url_with_port(self):
        environ = {
            "wsgi.url_scheme": "http",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "8080",
            "SCRIPT_NAME": "",
            "PATH_INFO": "/test",
            "QUERY_STRING": "",
        }
        url = get_current_url(environ)
        assert ":8080" in url

    def test_get_current_url_trusted_hosts_valid(self):
        environ = {
            "wsgi.url_scheme": "http",
            "HTTP_HOST": "example.com",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "80",
            "SCRIPT_NAME": "",
            "PATH_INFO": "/test",
            "QUERY_STRING": "",
        }
        url = get_current_url(environ, trusted_hosts=["example.com"])
        assert "example.com" in url

    def test_get_current_url_trusted_hosts_invalid(self):
        environ = {
            "wsgi.url_scheme": "http",
            "HTTP_HOST": "evil.com",
            "SERVER_NAME": "example.com",
            "SERVER_PORT": "80",
            "SCRIPT_NAME": "",
            "PATH_INFO": "/test",
            "QUERY_STRING": "",
        }
        with pytest.raises(Exception):  # SecurityError
            get_current_url(environ, trusted_hosts=["example.com"])


