class TestClosingIterator:
    def test_closing_iterator_basic(self):
        iterator = iter([b"a", b"b", b"c"])
        ci = ClosingIterator(iterator)
        assert next(ci) == b"a"
        assert next(ci) == b"b"
        assert next(ci) == b"c"

    def test_closing_iterator_callbacks(self):
        cleanup_called = []

        def cleanup():
            cleanup_called.append(True)

        iterator = iter([b"a", b"b"])
        ci = ClosingIterator(iterator, cleanup)
        list(ci)
        ci.close()
        assert len(cleanup_called) == 1

    def test_closing_iterator_multiple_callbacks(self):
        cleanup_calls = []

        def cleanup1():
            cleanup_calls.append(1)

        def cleanup2():
            cleanup_calls.append(2)

        iterator = iter([b"a"])
        ci = ClosingIterator(iterator, [cleanup1, cleanup2])
        list(ci)
        ci.close()
        assert sorted(cleanup_calls) == [1, 2]

    def test_closing_iterator_iterable_close(self):
        def custom_close():
            pass

        iterator = iter([b"a"])
        iterator.close = custom_close
        ci = ClosingIterator(iterator)
        ci.close()

    def test_closing_iterator_callable_callback(self):
        cleanup_called = []

        def cleanup():
            cleanup_called.append(True)

        iterator = iter([b"a"])
        ci = ClosingIterator(iterator, cleanup)
        list(ci)
        ci.close()
        assert len(cleanup_called) == 1


class TestFileWrapper:
    def test_file_wrapper_basic(self):
        file_obj = io.BytesIO(b"hello world")
        wrapper = FileWrapper(file_obj, buffer_size=5)
        chunks = list(wrapper)
        assert len(chunks) >= 1
        assert b"hello" in b"".join(chunks)

    def test_file_wrapper_close(self):
        file_obj = io.BytesIO(b"test")
        wrapper = FileWrapper(file_obj)
        wrapper.close()
        assert not file_obj.closed

    def test_file_wrapper_seekable(self):
        file_obj = io.BytesIO(b"test")
        wrapper = FileWrapper(file_obj)
        assert wrapper.seekable() is True

    def test_file_wrapper_seek(self):
        file_obj = io.BytesIO(b"hello world")
        wrapper = FileWrapper(file_obj)
        wrapper.seek(6)
        assert wrapper.tell() == 6

    def test_file_wrapper_tell(self):
        file_obj = io.BytesIO(b"hello world")
        wrapper = FileWrapper(file_obj)
        wrapper.seek(5)
        assert wrapper.tell() == 5


class TestRangeWrapper:
    def test_range_wrapper_basic(self):
        iterable = iter([b"hello world"])
        wrapper = _RangeWrapper(iterable, start_byte=6, byte_range=5)
        chunks = list(wrapper)
        assert b"world" in b"".join(chunks)

    def test_range_wrapper_seekable(self):
        file_obj = io.BytesIO(b"hello world")
        wrapper = _RangeWrapper(file_obj, start_byte=6, byte_range=5)
        assert wrapper.seekable is True

    def test_range_wrapper_end_reached(self):
        iterable = iter([b"abc"])
        wrapper = _RangeWrapper(iterable, start_byte=0, byte_range=3)
        list(wrapper)
