class TestLimitedStream:
    def test_limited_stream_read(self):
        stream = io.BytesIO(b"hello world")
        limited = LimitedStream(stream, limit=5)
        data = limited.read(3)
        assert data == b"hel"
        assert limited.tell() == 3

    def test_limited_stream_is_exhausted(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=5)
        limited.read(5)
        assert limited.is_exhausted is True

    def test_limited_stream_on_exhausted_max(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=5, is_max=True)
        limited.read(5)
        with pytest.raises(RequestEntityTooLarge):
            limited.read(1)

    def test_limited_stream_on_disconnect(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=10)
        limited._pos = 5
        with pytest.raises(ClientDisconnected):
            limited.on_disconnect()

    def test_limited_stream_on_disconnect_max_no_error(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=10, is_max=True)
        limited._pos = 5
        # Should not raise when is_max=True and no error
        limited.on_disconnect()

    def test_limited_stream_readinto(self):
        stream = io.BytesIO(b"hello world")
        limited = LimitedStream(stream, limit=5)
        buf = bytearray(10)
        size = limited.readinto(buf)
        assert size == 5
        assert buf[:5] == b"hello"

    def test_limited_stream_readall(self):
        stream = io.BytesIO(b"hello world")
        limited = LimitedStream(stream, limit=5)
        data = limited.readall()
        assert data == b"hello"

    def test_limited_stream_readall_exhausted(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=5)
        limited.read(5)
        data = limited.readall()
        assert data == b""

    def test_limited_stream_exhaust(self):
        stream = io.BytesIO(b"hello world")
        limited = LimitedStream(stream, limit=5)
        data = limited.exhaust()
        assert data == b"hello"

    def test_limited_stream_exhaust_already_exhausted(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=5)
        limited.read(5)
        data = limited.exhaust()
        assert data == b""

    def test_limited_stream_readable(self):
        stream = io.BytesIO(b"test")
        limited = LimitedStream(stream, limit=5)
        assert limited.readable() is True

    def test_limited_stream_read_zero_bytes(self):
        stream = io.BytesIO(b"")
        limited = LimitedStream(stream, limit=5)
        data = limited.read(1)
        assert data == b""

    def test_limited_stream_readinto_zero_remaining(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=5, is_max=True)
        limited.read(5)
        buf = bytearray(10)
        with pytest.raises(RequestEntityTooLarge):
            limited.readinto(buf)

    def test_limited_stream_read_error_handling(self):
        class FailingStream:
            def read(self, size):
                raise OSError("Connection lost")

        stream = FailingStream()
        limited = LimitedStream(stream, limit=10)
        buf = bytearray(10)
        result = limited.readinto(buf)
        assert result == 0

    def test_limited_stream_readinto_exception_handling(self):
        class FailingStream:
            def readinto(self, b):
                raise ValueError("Invalid")

        stream = FailingStream()
        limited = LimitedStream(stream, limit=10)
        buf = bytearray(10)
        result = limited.readinto(buf)
        assert result == 0

    def test_limited_stream_readall_with_disconnect(self):
        stream = io.BytesIO(b"hello")
        limited = LimitedStream(stream, limit=10)
        limited._pos = 5
        # Simulate disconnect by returning empty
        original_read = stream.read
        stream.read = lambda size: b""
        data = limited.readall()
        stream.read = original_read
        assert data == b""

    def test_limited_stream_position_tracking(self):
        stream = io.BytesIO(b"hello world")
        limited = LimitedStream(stream, limit=10)
        limited.read(3)
        assert limited.tell() == 3
        limited.read(2)
        assert limited.tell() == 5


