            "router": MagicMock(),
            "base_url": URL("http://testserver"),
        }
        scope["router"].url_path_for.return_value = URL("/path")
        conn = HTTPConnection(scope)
        url = conn.url_for("test_name")
        assert str(url) == "http://testserver/path"


