class TestRequest:
    @pytest.fixture
    def mock_receive(self):
        async def receive():
            return {"type": "http.disconnect"}

        return receive

    def test_init_http_scope(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)
        assert request.scope == scope

    def test_init_non_http_scope(self):
        scope = {"type": "websocket"}
        with pytest.raises(AssertionError):
            Request(scope)

    def test_method_property(self):
        scope = {"type": "http", "method": "POST"}
        request = Request(scope)
        assert request.method == "POST"

    def test_stream_consumed_twice(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)
        request._stream_consumed = True
        with pytest.raises(RuntimeError, match="Stream consumed"):
            anyio.run(request.stream().__anext__)

    def test_stream_body_cached(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)
        request._body = b"cached body"

        async def test():
            chunks = []
            async for chunk in request.stream():
                chunks.append(chunk)
            return chunks

        chunks = anyio.run(test)
        assert chunks == [b"cached body", b""]

    def test_stream_disconnect(self):
        scope = {"type": "http", "method": "GET"}

        async def receive():
            return {"type": "http.disconnect"}

        request = Request(scope, receive=receive)

        async def test():
            try:
                async for chunk in request.stream():
                    pass
            except ClientDisconnect:
                return True
            return False

        assert anyio.run(test) is True

    def test_body_method(self):
        scope = {"type": "http", "method": "GET"}

        async def receive():
            return {"type": "http.request", "body": b"test body", "more_body": False}

        request = Request(scope, receive=receive)

        async def test():
            return await request.body()

        assert anyio.run(test) == b"test body"

    def test_body_method_cached(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)
        request._body = b"cached"

        async def test():
            return await request.body()

        assert anyio.run(test) == b"cached"

    def test_json_method(self):
        scope = {"type": "http", "method": "POST"}

        async def receive():
            return {"type": "http.request", "body": b'{"key": "value"}', "more_body": False}

        request = Request(scope, receive=receive)

        async def test():
            return await request.json()

        result = anyio.run(test)
        assert result == {"key": "value"}

    def test_json_method_cached(self):
        scope = {"type": "http", "method": "POST"}
        request = Request(scope)
        request._json = {"cached": True}

        async def test():
            return await request.json()

        assert anyio.run(test) == {"cached": True}

    def test_close_method(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)
        request._form = FormData()

        async def test():
            await request.close()

        anyio.run(test)

    def test_close_method_no_form(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)

        async def test():
            await request.close()

        anyio.run(test)

    def test_is_disconnected_false(self):
        scope = {"type": "http", "method": "GET"}

        async def receive():
            return {"type": "http.request", "body": b"", "more_body": False}

        request = Request(scope, receive=receive)

        async def test():
            return await request.is_disconnected()

        assert anyio.run(test) is False

    def test_is_disconnected_true(self):
        scope = {"type": "http", "method": "GET"}

        async def receive():
            return {"type": "http.disconnect"}

        request = Request(scope, receive=receive)

        async def test():
            return await request.is_disconnected()

        assert anyio.run(test) is True

    def test_send_push_promise_no_extension(self):
        scope = {"type": "http", "method": "GET"}
        request = Request(scope)

        async def test():
            await request.send_push_promise("/pushed")

        # Should not raise if no extension
        anyio.run(test)

    def test_send_push_promise_with_extension(self):
        scope = {
            "type": "http",
            "method": "GET",
            "extensions": {"http.response.push": {}},
            "headers": [(b"accept", b"text/html")],
        }

        messages = []

        async def send(message):
            messages.append(message)

        request = Request(scope, send=send)

        async def test():
            await request.send_push_promise("/pushed")

        anyio.run(test)
        assert len(messages) == 1
        assert messages[0]["type"] == "http.response.push"
        assert messages[0]["path"] == "/pushed"


class TestRequestFormParsing:
    @pytest.fixture(autouse=True)
    def mock_parse_options_header(self):
        with patch("starlette.requests.parse_options_header") as mock:
            mock.return_value = (b"application/x-www-form-urlencoded", {})
            yield mock

    def test_form_method_returns_awaitable(self):
        scope = {"type": "http", "method": "POST"}
        request = Request(scope)

        result = request.form()
        assert hasattr(result, "__await__")

    def test_form_multipart_not_installed(self):
        scope = {"type": "http", "method": "POST"}

        with patch("starlette.requests.parse_options_header") as mock:
            mock.return_value = (b"multipart/form-data", {})

            with patch("starlette.requests.MultiPartParser") as mock_parser:
                mock_parser.side_effect = ImportError("not installed")

                request = Request(scope)

                async def test():
                    try:
                        await request.form()
                    except ImportError:
                        return True
                    return False

                assert anyio.run(test) is True

    def test_form_application_x_www_form_urlencoded(self):
        scope = {"type": "http", "method": "POST"}

        async def receive():
            return {"type": "http.request", "body": b"key=value", "more_body": False}

        request = Request(scope, receive=receive)

        async def test():
            form = await request.form()
            return dict(form)

        result = anyio.run(test)
        assert "key" in result

    def test_form_multipart(self):
        scope = {"type": "http", "method": "POST"}

        async def receive():
            return {"type": "http.request", "body": b"test", "more_body": False}

        with patch("starlette.requests.MultiPartParser") as mock_parser:
            mock_instance = MagicMock()
            mock_instance.parse = AsyncMock(return_value=FormData())
            mock_parser.return_value = mock_instance

            request = Request(scope, receive=receive)

            async def test():
                form = await request.form()
                return form

            result = anyio.run(test)
            assert isinstance(result, FormData)


